//! Shared vectors for `core/bitcoin`: generated by replaying the upstream
//! `spark-frost` transaction/HTLC/sequence functions, consumed byte-for-byte by
//! the TypeScript implementation.
//!
//! `SPARK_WRITE_VECTORS=1 cargo test --test bitcoin` regenerates
//! `vectors/transactions.json`; otherwise the test asserts the stored file is
//! identical to what the pinned upstream revision produces.

#![allow(
    unused_crate_dependencies,
    clippy::tests_outside_test_module,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::missing_panics_doc,
    reason = "test code"
)]

use std::path::{Path, PathBuf};

use bitcoin::absolute::LockTime;
use bitcoin::consensus::serialize;
use bitcoin::hashes::Hash;
use bitcoin::key::Secp256k1;
use bitcoin::secp256k1::{PublicKey, SecretKey};
use bitcoin::transaction::{OutPoint, Sequence, TxIn, TxOut, Version};
use bitcoin::{Address, Amount, ScriptBuf, Transaction, Witness};
use serde_json::{Value, json};
use spark_frost::{htlc, transaction};

mod common;
use common::UPSTREAM_REV;

const FEE: u64 = 955;

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../vectors")
        .canonicalize()
        .unwrap()
}

fn hex_str(bytes: &[u8]) -> String {
    hex::encode(bytes)
}

fn pubkey(seed: u8) -> bitcoin::PublicKey {
    let secret = SecretKey::from_slice(&[seed; 32]).unwrap();
    PublicKey::from_secret_key(&Secp256k1::new(), &secret).into()
}

fn xonly(seed: u8) -> bitcoin::secp256k1::XOnlyPublicKey {
    pubkey(seed).inner.x_only_public_key().0
}

fn p2tr_script(pubkey: &bitcoin::PublicKey) -> ScriptBuf {
    transaction::p2tr_script_from_pubkey_bytes(&pubkey.to_bytes(), bitcoin::Network::Bitcoin)
        .unwrap()
}

/// Deterministic parent "deposit" transaction: one fake input and two P2TR
/// outputs so vectors can exercise `vout` selection and multi-input sighashes.
fn parent_tx(amount0: u64, amount1: u64) -> Vec<u8> {
    let tx = Transaction {
        version: Version::TWO,
        lock_time: LockTime::ZERO,
        input: vec![TxIn {
            previous_output: OutPoint::new(
                bitcoin::Txid::from_raw_hash(Hash::from_byte_array([0x22; 32])),
                1,
            ),
            script_sig: ScriptBuf::new(),
            sequence: Sequence::MAX,
            witness: Witness::new(),
        }],
        output: vec![
            TxOut {
                value: Amount::from_sat(amount0),
                script_pubkey: p2tr_script(&pubkey(0xA1)),
            },
            TxOut {
                value: Amount::from_sat(amount1),
                script_pubkey: p2tr_script(&pubkey(0xA2)),
            },
        ],
    };
    serialize(&tx)
}

fn p2tr_address(seed: u8, network: bitcoin::Network) -> String {
    Address::p2tr(&Secp256k1::verification_only(), xonly(seed), None, network).to_string()
}

fn tx_result(result: &transaction::InternalTransactionResult) -> Value {
    json!({
        "tx": hex_str(&result.tx_bytes),
        "sighash": hex_str(&result.sighash),
    })
}

fn sequence_cases() -> Value {
    let timelock: Vec<Value> = [0u32, 2000, 0x4000_07d0, 0xFFFF_FFFF]
        .iter()
        .map(|&s| {
            json!({
                "sequence": s,
                "timelock": transaction::get_timelock_from_sequence(s),
            })
        })
        .collect();

    let valid: Vec<Value> = [
        0u32,
        2000,
        0x4000_07d0,
        0x8000_0000,
        0x0040_0000,
        0x0001_0000,
    ]
    .iter()
    .map(|&s| {
        json!({
            "sequence": s,
            "ok": transaction::check_if_valid_sequence(s).is_ok(),
        })
    })
    .collect();

    let zero: Vec<Value> = [0u32, 100, 0x4000_0000, 0x0001_0000]
        .iter()
        .map(|&s| {
            json!({
                "sequence": s,
                "zero": transaction::is_zero_timelock(s),
            })
        })
        .collect();

    let round_down: Vec<Value> = [
        (2000u32, 100u32),
        (1999, 100),
        (1, 100),
        (2000, 0),
        (0xFFFF, 7),
    ]
    .iter()
    .map(|&(t, i)| {
        json!({
            "timelock": t,
            "interval": i,
            "result": transaction::round_down_to_timelock_interval(t, i),
        })
    })
    .collect();

    let next: Vec<Value> = [
        (2000u32, 100u32, 50u32),
        (100, 100, 50),
        (0, 100, 50),
        (50, 100, 50),
        (0x4000_07d0, 100, 50),
        (0x0001_0000 | 0x07d0, 100, 50),
        (2000, 100, 0xFFFF),
    ]
    .iter()
    .map(
        |&(curr, interval, offset)| match transaction::next_sequence(curr, interval, offset) {
            Ok((next_seq, next_direct)) => json!({
                "sequence": curr,
                "interval": interval,
                "offset": offset,
                "ok": true,
                "nextSequence": next_seq,
                "nextDirectSequence": next_direct,
            }),
            Err(_) => json!({
                "sequence": curr,
                "interval": interval,
                "offset": offset,
                "ok": false,
            }),
        },
    )
    .collect();

    json!({
        "getTimelockFromSequence": timelock,
        "checkIfValidSequence": valid,
        "isZeroTimelock": zero,
        "roundDownToTimelockInterval": round_down,
        "nextSequence": next,
    })
}

fn node_pair_cases() -> Vec<Value> {
    let parent = parent_tx(100_000, 3_000);
    let small_parent = parent_tx(500, 2_000);
    let cases = [
        ("initial", &parent, 0u32, "mainnet", 2000u32, 2050u32),
        ("zero-timelock", &parent, 0, "mainnet", 0, 50),
        ("decremented", &parent, 0, "mainnet", 1900, 1950),
        (
            "bit30",
            &parent,
            0,
            "mainnet",
            0x4000_07d0,
            0x4000_07d0 + 50,
        ),
        ("vout1", &parent, 1, "regtest", 2000, 2050),
        ("amount-below-fee", &small_parent, 0, "mainnet", 2000, 2050),
    ];
    cases
        .iter()
        .map(|&(name, parent, vout, net, seq, dseq)| {
            let address = match net {
                "mainnet" => p2tr_address(0xB0, bitcoin::Network::Bitcoin),
                _ => p2tr_address(0xB0, bitcoin::Network::Regtest),
            };
            let pair = transaction::construct_node_tx_pair(parent, vout, &address, seq, dseq, FEE)
                .unwrap();
            json!({
                "name": name,
                "parentTx": hex_str(parent),
                "vout": vout,
                "address": address,
                "sequence": seq,
                "directSequence": dseq,
                "feeSats": FEE,
                "cpfp": tx_result(&pair.cpfp),
                "direct": tx_result(&pair.direct),
            })
        })
        .collect()
}

fn refund_trio_cases() -> Vec<Value> {
    let parent = parent_tx(100_000, 3_000);
    let mut cases = Vec::new();
    for (name, network, seq, dseq, include_direct) in [
        ("mainnet", "mainnet", 2000u32, 2050u32, true),
        ("regtest", "regtest", 1900, 1950, true),
        ("zero-timelock", "mainnet", 0, 50, false),
    ] {
        let address = p2tr_address(0xA1, bitcoin::Network::Bitcoin);
        let pair =
            transaction::construct_node_tx_pair(&parent, 0, &address, seq, dseq, FEE).unwrap();
        let direct_bytes = include_direct.then(|| pair.direct.tx_bytes.clone());
        let trio = transaction::construct_refund_tx_trio(
            &pair.cpfp.tx_bytes,
            direct_bytes.as_deref(),
            0,
            &pubkey(0xC0).to_bytes(),
            network,
            seq,
            dseq,
            FEE,
        )
        .unwrap();
        cases.push(json!({
            "name": name,
            "nodeTx": hex_str(&pair.cpfp.tx_bytes),
            "directNodeTx": direct_bytes.as_ref().map(|b| hex_str(b)),
            "vout": 0,
            "receivingPublicKey": hex_str(&pubkey(0xC0).to_bytes()),
            "network": network,
            "sequence": seq,
            "directSequence": dseq,
            "feeSats": FEE,
            "cpfpRefund": tx_result(&trio.cpfp_refund),
            "directRefund": trio.direct_refund.as_ref().map(tx_result),
            "directFromCpfpRefund": tx_result(&trio.direct_from_cpfp_refund),
        }));
    }
    cases
}

fn htlc_cases() -> Vec<Value> {
    let parent = parent_tx(100_000, 3_000);
    let address = p2tr_address(0xA1, bitcoin::Network::Bitcoin);
    let pair = transaction::construct_node_tx_pair(&parent, 0, &address, 2000, 2050, FEE).unwrap();
    let payment_hash = [0x55u8; 32];
    let hashlock = pubkey(0xD1).to_bytes();
    let seqlock = pubkey(0xD2).to_bytes();
    let destination = pubkey(0xE0).to_bytes();

    let htlc_tx = htlc::construct_htlc_transaction(
        &pair.cpfp.tx_bytes,
        0,
        2000,
        &payment_hash,
        &hashlock,
        &seqlock,
        2160,
        false,
        FEE,
        "mainnet",
    )
    .unwrap();
    let htlc_tx_fee = htlc::construct_htlc_transaction(
        &pair.cpfp.tx_bytes,
        0,
        1900,
        &payment_hash,
        &hashlock,
        &seqlock,
        2160,
        true,
        FEE,
        "regtest",
    )
    .unwrap();
    let sender = htlc::construct_htlc_sender_spend(
        &htlc_tx.tx_bytes,
        &destination,
        &payment_hash,
        &hashlock,
        &seqlock,
        2160,
        FEE,
        "mainnet",
    )
    .unwrap();
    let receiver = htlc::construct_htlc_receiver_spend(
        &htlc_tx.tx_bytes,
        &destination,
        &payment_hash,
        &hashlock,
        &seqlock,
        2160,
        FEE,
        "mainnet",
    )
    .unwrap();

    vec![
        json!({
            "name": "cpfp",
            "nodeTx": hex_str(&pair.cpfp.tx_bytes),
            "vout": 0,
            "sequence": 2000,
            "paymentHash": hex_str(&payment_hash),
            "hashLockPublicKey": hex_str(&hashlock),
            "sequenceLockPublicKey": hex_str(&seqlock),
            "htlcSequence": 2160,
            "applyFee": false,
            "feeSats": FEE,
            "network": "mainnet",
            "tx": hex_str(&htlc_tx.tx_bytes),
            "sighash": hex_str(&htlc_tx.sighash),
        }),
        json!({
            "name": "fee",
            "nodeTx": hex_str(&pair.cpfp.tx_bytes),
            "vout": 0,
            "sequence": 1900,
            "paymentHash": hex_str(&payment_hash),
            "hashLockPublicKey": hex_str(&hashlock),
            "sequenceLockPublicKey": hex_str(&seqlock),
            "htlcSequence": 2160,
            "applyFee": true,
            "feeSats": FEE,
            "network": "regtest",
            "tx": hex_str(&htlc_tx_fee.tx_bytes),
            "sighash": hex_str(&htlc_tx_fee.sighash),
        }),
        json!({
            "name": "sender-spend",
            "htlcTx": hex_str(&htlc_tx.tx_bytes),
            "destinationPublicKey": hex_str(&destination),
            "paymentHash": hex_str(&payment_hash),
            "hashLockPublicKey": hex_str(&hashlock),
            "sequenceLockPublicKey": hex_str(&seqlock),
            "htlcSequence": 2160,
            "feeSats": FEE,
            "network": "mainnet",
            "tx": hex_str(&sender.tx_bytes),
            "sighash": hex_str(&sender.sighash),
            "script": hex_str(&sender.script),
            "controlBlock": hex_str(&sender.control_block),
        }),
        json!({
            "name": "receiver-spend",
            "htlcTx": hex_str(&htlc_tx.tx_bytes),
            "destinationPublicKey": hex_str(&destination),
            "paymentHash": hex_str(&payment_hash),
            "hashLockPublicKey": hex_str(&hashlock),
            "sequenceLockPublicKey": hex_str(&seqlock),
            "htlcSequence": 2160,
            "feeSats": FEE,
            "network": "mainnet",
            "tx": hex_str(&receiver.tx_bytes),
            "sighash": hex_str(&receiver.sighash),
            "script": hex_str(&receiver.script),
            "controlBlock": hex_str(&receiver.control_block),
        }),
    ]
}

fn multi_input_sighash_cases() -> Vec<Value> {
    let parent = parent_tx(100_000, 3_000);
    // A two-input consolidation paying a single P2TR output + anchor.
    let prev0 = p2tr_script(&pubkey(0xA1));
    let prev1 = p2tr_script(&pubkey(0xA2));
    let tx = Transaction {
        version: Version::non_standard(3),
        lock_time: LockTime::ZERO,
        input: vec![
            TxIn {
                previous_output: OutPoint::new(
                    bitcoin::consensus::deserialize::<Transaction>(&parent)
                        .unwrap()
                        .compute_txid(),
                    0,
                ),
                script_sig: ScriptBuf::new(),
                sequence: Sequence::ZERO,
                witness: Witness::new(),
            },
            TxIn {
                previous_output: OutPoint::new(
                    bitcoin::consensus::deserialize::<Transaction>(&parent)
                        .unwrap()
                        .compute_txid(),
                    1,
                ),
                script_sig: ScriptBuf::new(),
                sequence: Sequence::ZERO,
                witness: Witness::new(),
            },
        ],
        output: vec![
            TxOut {
                value: Amount::from_sat(103_000),
                script_pubkey: prev0.clone(),
            },
            transaction::ephemeral_anchor_output(),
        ],
    };
    let tx_bytes = serialize(&tx);
    [0u32, 1]
        .iter()
        .map(|&input_index| {
            let sighash = transaction::compute_multi_input_sighash(
                &tx_bytes,
                input_index,
                &[prev0.to_bytes(), prev1.to_bytes()],
                &[100_000, 3_000],
            )
            .unwrap();
            json!({
                "tx": hex_str(&tx_bytes),
                "inputIndex": input_index,
                "prevOutScripts": [hex_str(&prev0.to_bytes()), hex_str(&prev1.to_bytes())],
                "prevOutValues": [100_000u64, 3_000u64],
                "sighash": hex_str(&sighash),
            })
        })
        .collect()
}

#[test]
fn vectors_transactions() {
    let document = json!({
        "header": {
            "source": "upstream spark-frost transaction.rs + htlc.rs",
            "upstream": format!("buildonspark/spark@{UPSTREAM_REV}"),
            "note": "Test vectors only. Never use these keys for funds.",
        },
        "sequence": sequence_cases(),
        "nodeTxPairs": node_pair_cases(),
        "refundTxTrios": refund_trio_cases(),
        "htlc": htlc_cases(),
        "multiInputSighash": multi_input_sighash_cases(),
    });

    let path = vectors_dir().join("transactions.json");
    if std::env::var_os("SPARK_WRITE_VECTORS").is_some() {
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&document).unwrap() + "\n",
        )
        .unwrap();
        return;
    }
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(
        stored, document,
        "transactions.json differs; regenerate with SPARK_WRITE_VECTORS=1"
    );
}
